package org.deposit.it;
import static org.junit.jupiter.api.Assertions.*;
import static org.deposit.it.Stage1LifecycleIT.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;

@Timeout(120)
class Stage5ProbeIT {
    @BeforeAll static void start(){connect();Stage4ProbeIT.ensureAccount();Stage5CoreIT.token=Stage3CoreIT.login();}
    @AfterAll static void stop(){close();}
    @BeforeEach void fixture(){Stage5CoreIT.fixture5();}
    @AfterEach void reset(){Stage4ProbeIT.arm("","clear");query("CALL stage0.security.clock(0)",Map.of());}
    @Test void historyFailureRollsBackDomainRetentionSequenceAndReceipt(){String token=Stage5CoreIT.token;long seq=Stage5CoreIT.seq(),records=Stage5CoreIT.count("Revision");var context=write(token,seq);Stage4ProbeIT.arm("history-before-receipt","fail");error("INTERNAL_ERROR",()->call("deposit.set.descriptor",m("objectId",Stage5CoreIT.object,"name","Mass","value",20L),context));assertEquals(10L,Stage5CoreIT.value());assertEquals(seq,Stage5CoreIT.seq());assertEquals(records,Stage5CoreIT.count("Revision"));assertEquals(0,query("MATCH (r:DepositReceipt {operationId:$op}) RETURN count(r) AS n",m("op",context.get("operationId"))).getFirst().get("n").asInt());}
    @Test void expiryBeforeCommitAndCancellationRollbackHistory()throws Exception {String token=Stage5CoreIT.token;long before=Stage5CoreIT.seq();try(var s=driver.session();var tx=s.beginTransaction()){tx.run("CALL deposit.set.descriptor($r,$c)",m("r",m("objectId",Stage5CoreIT.object,"name","Mass","value",20L),"c",write(token,before))).consume();query("CALL stage0.security.clock(1800001)",Map.of());assertThrows(org.neo4j.driver.exceptions.ClientException.class,tx::commit);}query("CALL stage0.security.clock(0)",Map.of());Stage5CoreIT.token=Stage3CoreIT.login();Stage3CoreIT.select(Stage5CoreIT.token,Stage5CoreIT.ns);assertEquals(before,Stage5CoreIT.seq());assertEquals(10L,Stage5CoreIT.value());try(var session=driver.session();var tx=session.beginTransaction()){var context=write(Stage5CoreIT.token,before);tx.run("CALL deposit.set.descriptor($r,$c)",m("r",m("objectId",Stage5CoreIT.object,"name","Mass","value",30L),"c",context)).consume();call("deposit.utils.cancel",m("requestId",context.get("requestId")),ctx(Stage5CoreIT.token));assertThrows(org.neo4j.driver.exceptions.Neo4jException.class,tx::commit);}assertEquals(before,Stage5CoreIT.seq());}
    @Test void geometryReversalFaultsAndSingleLiveIndex(){Stage5CoreIT.stage4();var g=Stage4CoreIT.descriptor("G","DGeometry",Stage4CoreIT.geometry("POINT Z (1 2 3)",4326L,3));String gid=g.get("data").get("geometryId").asString();String changed=Stage5CoreIT.rid(Stage5CoreIT.change("deposit.set.descriptor",m("objectId",Stage5CoreIT.object,"name","G","value",Stage4CoreIT.geometry("POINT Z (9 8 7)",999999L,3))));for(String point:List.of("geometry-removal","geometry-update","geometry-registration")){var old=Stage4ProbeIT.inspect();long seq=Stage5CoreIT.seq();Stage4ProbeIT.arm(point,"fail");error("INTERNAL_ERROR",()->Stage5CoreIT.undo(changed));assertEquals(seq,Stage5CoreIT.seq());assertEquals(old,Stage4ProbeIT.inspect());}Stage4ProbeIT.arm("","clear");Stage5CoreIT.undo(changed);var layers=Stage4ProbeIT.inspect().get("layers").asList(v->v);assertEquals(1L,layers.stream().mapToLong(v->v.get("count").asLong()).sum());var entries=layers.stream().flatMap(v->v.get("entries").asList(x->x).stream()).toList();assertEquals(gid,entries.getFirst().get("id").asString());assertEquals(List.of(1.,2.,1.,2.),entries.getFirst().get("bbox").asList());assertEquals(0,query("MATCH (s:DepositSnapshot)-[:RTREE_REFERENCE]->() RETURN count(s) AS n",Map.of()).getFirst().get("n").asInt());}
    @Test void corruptHistoricalCategoryAndMissingSchemaRejectWithoutWrites(){String target=Stage5CoreIT.head(),token=Stage5CoreIT.token;long seq=Stage5CoreIT.seq();query("MATCH (r:Revision {id:$id})-[:HAS_CHANGE]->(s:DepositSnapshot {entityKind:'Object'}) SET s.entityKind='Class'",m("id",target));error("REVISION_CONFLICT",()->call("deposit.get.restorePreview",m("targetRevisionId",target),ctx(token)));error("REVISION_CONFLICT",()->Stage5CoreIT.change("deposit.utils.restore",m("targetRevisionId",target)));assertEquals(seq,Stage5CoreIT.seq());query("MATCH (r:Revision {id:$id})-[:HAS_CHANGE]->(s:DepositSnapshot) WHERE s.afterJson CONTAINS '\"kind\":\"Object\"' SET s.entityKind='Object'",m("id",target));var damaged=query("MATCH (s:DepositSnapshot {namespaceId:$ns,entityKind:'ClassDescriptor'}) RETURN s.id AS id,s.afterJson AS image",m("ns",Stage5CoreIT.ns)).getFirst();query("MATCH (s:DepositSnapshot {id:$id}) SET s.afterJson=replace(s.afterJson,$class,'missing-class')",m("id",damaged.get("id").asString(),"class",Stage5CoreIT.clazz));error("REVISION_CONFLICT",()->call("deposit.get.restorePreview",m("targetRevisionId",target),ctx(token)));assertEquals(seq,Stage5CoreIT.seq());query("MATCH (s:DepositSnapshot {id:$id}) SET s.afterJson=$image",m("id",damaged.get("id").asString(),"image",damaged.get("image").asString()));}
    @Test void historyOnlyEditorReattachmentAndRevocation(){Stage5CoreIT.stage4();String resource=Stage4CoreIT.upload(Stage4CoreIT.ABC,"editor-history");String editor=Stage5CoreIT.actor("editor");call("deposit.set.descriptor",m("objectId",Stage5CoreIT.object,"name","File","value",m("type","DResource","value",m("resourceId",resource))),write(Stage5CoreIT.token,Stage5CoreIT.seq()));String removal=Stage5CoreIT.rid(call("deposit.set.descriptor",m("objectId",Stage5CoreIT.object,"name","File","value",null),write(editor,Stage5CoreIT.seq())));query("MATCH (l:DepositResourceLocation {id:$id}) SET l.leaseUntil=0",m("id",resource));assertEquals("YWJj",call("deposit.resource.downloadChunk",m("resourceId",resource,"offset",0L,"length",3L),ctx(editor)).get("data").get("bytesBase64").asString());call("deposit.utils.undo",m("revisionId",removal),write(editor,Stage5CoreIT.seq()));String actor=query("MATCH (r:Revision {id:$id}) RETURN r.actorId AS id",m("id",removal)).getFirst().get("id").asString();Stage5CoreIT.change("deposit.set.namespaceRole",m("userId",actor,"role",null));error("NOT_FOUND",()->call("deposit.resource.info",m("resourceId",resource),ctx(editor)));}
    @Test void historyReadRejectsConcurrentSequenceChange()throws Exception {String token=Stage5CoreIT.token;Stage4ProbeIT.arm("history-read-row","pause");try(var pool=Executors.newSingleThreadExecutor()){var read=pool.submit(()->query("CALL deposit.get.history({},$c)",m("c",ctx(token))));var marker=ROOT.resolve("stage4-pause.json");long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(15);while(!java.nio.file.Files.exists(marker)&&System.nanoTime()<until)Thread.sleep(20);assertTrue(java.nio.file.Files.exists(marker));Stage5CoreIT.mass(100);Stage4ProbeIT.arm("","clear");var failure=assertThrows(ExecutionException.class,()->read.get(15,TimeUnit.SECONDS));assertTrue(failure.getCause().getMessage().contains("REVISION_CONFLICT"));}}
    @Test void historyReadSerializesReattachmentAndCollection()throws Exception {Stage5CoreIT.stage4();String resource=Stage4CoreIT.upload(Stage4CoreIT.ABC,"race-history");Stage4CoreIT.descriptor("F","DResource",m("resourceId",resource));String removal=Stage5CoreIT.rid(Stage5CoreIT.change("deposit.set.descriptor",m("objectId",Stage5CoreIT.object,"name","F","value",null)));Stage4CoreIT.assertStored(resource);query("MATCH (l:DepositResourceLocation {id:$id}) SET l.leaseUntil=0,l.orphanSince=0",m("id",resource));try(var session=driver.session();var tx=session.beginTransaction();var pool=Executors.newSingleThreadExecutor()){assertEquals("YWJj",tx.run("CALL deposit.resource.downloadChunk($r,$c)",m("r",m("resourceId",resource,"offset",0L,"length",3L),"c",ctx(Stage5CoreIT.token))).single().get("data").get("bytesBase64").asString());var entered=new CountDownLatch(1);var restore=pool.submit(()->{entered.countDown();return Stage5CoreIT.undo(removal);});assertTrue(entered.await(5,TimeUnit.SECONDS));assertThrows(TimeoutException.class,()->restore.get(250,TimeUnit.MILLISECONDS));tx.commit();assertNotNull(restore.get(20,TimeUnit.SECONDS));}Stage4CoreIT.assertStored(resource);assertFalse(call("deposit.admin.pruneResources",m("minimumAgeHours",0L),ctx(Stage5CoreIT.token)).get("data").get("candidateIds").asList().contains(resource));assertArrayEquals(Stage4CoreIT.ABC,java.nio.file.Files.readAllBytes(Stage4CoreIT.resourcePath(resource)));}
    @Test void corruptionBeforeRetentionFailsWholeAction()throws Exception {Stage5CoreIT.stage4();String resource=Stage4CoreIT.upload(Stage4CoreIT.ABC,"corrupt-retention");Stage4CoreIT.descriptor("F","DResource",m("resourceId",resource));var path=Stage4CoreIT.resourcePath(resource);byte[] bytes=java.nio.file.Files.readAllBytes(path);long sequence=Stage5CoreIT.seq(),records=Stage5CoreIT.count("Revision");try{java.nio.file.Files.write(path,new byte[]{0,0,0});error("RESOURCE_CORRUPT",()->Stage5CoreIT.change("deposit.set.descriptor",m("objectId",Stage5CoreIT.object,"name","F","value",null)));assertEquals(sequence,Stage5CoreIT.seq());assertEquals(records,Stage5CoreIT.count("Revision"));assertEquals(resource,call("deposit.get.descriptor",m("objectId",Stage5CoreIT.object,"name","F"),ctx(Stage5CoreIT.token)).get("data").get("value").get("resourceId").asString());}finally{java.nio.file.Files.write(path,bytes);}}
}
